window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5118a7711cf2b8fa"]={"versions": [{"id": "FIG-5118a7711cf2b8fa", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des M2-Metamodells der AUTOSAR Foundation / Standardization Template).\n</li><li><strong>Technischer Zweck:</strong> Modellierung des Scoping-Mechanismus für Spezifikationselemente (<code>SpecElementScope</code>). Es definiert die semantische Einbindung und Gültigkeit von Standard-Spezifikationselementen (z. B. Requirements, Blueprints, Interfaces, Module) innerhalb definierter Standardisierungs-Profile, Teilspezifikationen oder OEM-/Plattform-Kontexte gemäß <code>RS_STDT_00103</code>, <code>RS_STDT_00106</code> und <code>RS_STDT_00109</code>.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Klassen</h5>\n<ul class=\"fig-list\"><li><strong><code>MultilanguageReferrable</code> / <code>Identifiable</code> (Abstrakte Basisklasse):</strong>\n<ul class=\"fig-list\"><li>Wurzelelement des AUTOSAR-Metamodells zur globalen Identifizierbarkeit und Lokalisierung.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>category: CategoryString [0..1]</code> – Typisierung/Klassifizierung des Elements.\n</li><li><code>uuid: String [0..1]</code> – Eindeutiger Identifikator nach RFC 4122.\n</li></ul>\n</li><li>Geerbte Basiseigenschaften (aus <code>Referrable</code>): <code>shortName</code> als modellweiter Referenzanker.\n</li></ul>\n</li><li><strong><code>MultiLanguageOverviewParagraph</code>:</strong>\n<ul class=\"fig-list\"><li>Strukturierter, mehrsprachiger Textabsatz für Kurzbeschreibungen.\n</li></ul>\n</li><li><strong><code>DocumentationBlock</code>:</strong>\n<ul class=\"fig-list\"><li>Ausführlicher Dokumentationscontainer.\n</li><li><strong>Stereotyp <code>«atpMixed»</code>:</strong> Definiert gemischten Content (Mischung aus freiem Fließtext, Formatierungsstrukturen und semantischen Metamodell-Inline-Tags).\n</li></ul>\n</li><li><strong><code>SpecElementReference</code> (Abstrakte Spezialisierung):</strong>\n<ul class=\"fig-list\"><li>Generalisiert <code>MultilanguageReferrable</code>.\n</li><li>Attribut:\n<ul class=\"fig-list\"><li><code>alternativeName: String [0..1]</code> – Optionaler Sekundärname bzw. systemspezifischer Alias für das Spezifikationselement.\n</li></ul>\n</li></ul>\n</li><li><strong><code>SpecElementScope</code> (Konkrete Spezialisierung):</strong>\n<ul class=\"fig-list\"><li>Generalisiert <code>SpecElementReference</code>.\n</li><li>Attribut:\n<ul class=\"fig-list\"><li><code>inScope: Boolean [0..1]</code> – Binärer Schalter (<code>true</code> / <code>false</code>) zur expliziten Ein- oder Ausgrenzung des Elements im spezifizierten Kontext.\n</li></ul>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Komposition <code>+desc</code> (<code>0..1</code>):</strong> <code>MultilanguageReferrable</code> aggregiert exklusiv maximal einen <code>MultiLanguageOverviewParagraph</code>.\n</li><li><strong>Komposition <code>+introduction</code> (<code>0..1</code>):</strong> <code>MultilanguageReferrable</code> aggregiert exklusiv maximal einen <code>DocumentationBlock</code>.\n</li><li><strong>Generalisierung:</strong> <code>SpecElementReference</code> erbt von <code>MultilanguageReferrable</code>.\n</li><li><strong>Generalisierung:</strong> <code>SpecElementScope</code> erbt von <code>SpecElementReference</code> (und damit transitiv von <code>Identifiable</code> und <code>Referrable</code>).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li><strong>Laufzeitverhalten:</strong> Nicht zutreffend (rein deklaratives M2-Strukturmetamodell; keine Ausführung zur Target-Laufzeit auf BSW/RTE-Ebene).\n</li><li><strong>Tooling- &amp; Transformationsablauf (Entwurfszeit):</strong>\n<ol class=\"fig-list\"><li><strong>Deklaration:</strong> Ein Standardization-Profile instanziiert ein <code>SpecElementScope</code> für ein konkretes Spezifikationselement.\n</li><li><strong>Scoping-Prüfung (<code>TPS_STDT_00124</code>):</strong>\n<ul class=\"fig-list\"><li><code>inScope == true</code>: Element ist zwingender/aktiver Bestandteil des definierten Standards/Profils.\n</li><li><code>inScope == false</code>: Element wird explizit als „out of scope“ markiert (wichtig für Profil-Tailoring und Teilspezifikationen).\n</li><li>Fehlt das Attribut (<code>[0..1]</code>), greifen profilweite Default-Semantiken der Standardization-Toolchain.\n</li></ul>\n</li><li><strong>Dokumenten- &amp; Blueprint-Synthese:</strong> Toolchains evaluieren <code>desc</code> und <code>introduction</code> zur automatisierten Dokumenten-Generierung und Blueprint-Validierung.\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Target-Auswirkung (Embedded/C++):</strong> Keine direkten Auswirkungen auf MCAL-, BSW- oder SWC-Quellcode. Es existieren keine generierten C-APIs, ISRs oder Mailbox-Strukturen für dieses Metamodell-Element.\n</li><li><strong>Konfigurations- &amp; Modellierungsverträge (ARXML):</strong>\n<ul class=\"fig-list\"><li><code>SpecElementScope</code> wird primär in AUTOSAR Blueprint-Katalogen (<code>AUTOSAR_MOD_StandardizationTemplate.arxml</code>) und Spezifikationsmetadaten verwendet.\n</li><li>Relevanz für Platform-Architekten und Tool-Entwickler: Ermöglicht das präzise Zuschneiden (Tailoring) von Standard-Features für Classic- bzw. Adaptive-Plattformen.\n</li><li>Bei der Definition herstellerspezifischer Derivate verhindert die explizite Kennzeichnung <code>inScope: false</code> Implementierungsambiguitäten bezüglich Konformitätsanforderungen (Compliance Gates / SWS Conformance Testing).\n</li></ul>\n</li></ul>"}, {"id": "FIG-9b2d97b54547876a", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des M2-Metamodells der AUTOSAR Foundation / Standardization Template).\n</li><li><strong>Technischer Zweck:</strong> Modellierung des Scoping-Mechanismus für Spezifikationselemente (<code>SpecElementScope</code>). Es definiert die semantische Einbindung und Gültigkeit von Standard-Spezifikationselementen (z. B. Requirements, Blueprints, Interfaces, Module) innerhalb definierter Standardisierungs-Profile, Teilspezifikationen oder OEM-/Plattform-Kontexte gemäß <code>RS_STDT_00103</code>, <code>RS_STDT_00106</code> und <code>RS_STDT_00109</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Klassen</h5>\n<ul class=\"fig-list\"><li><strong><code>MultilanguageReferrable</code> / <code>Identifiable</code> (Abstrakte Basisklasse):</strong>\n<ul class=\"fig-list\"><li>Wurzelelement des AUTOSAR-Metamodells zur globalen Identifizierbarkeit und Lokalisierung.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>category: CategoryString [0..1]</code> – Typisierung/Klassifizierung des Elements.\n</li><li><code>uuid: String [0..1]</code> – Eindeutiger Identifikator nach RFC 4122.\n</li></ul>\n</li><li>Geerbte Basiseigenschaften (aus <code>Referrable</code>): <code>shortName</code> als modellweiter Referenzanker.\n</li></ul>\n</li><li><strong><code>MultiLanguageOverviewParagraph</code>:</strong>\n<ul class=\"fig-list\"><li>Strukturierter, mehrsprachiger Textabsatz für Kurzbeschreibungen.\n</li></ul>\n</li><li><strong><code>DocumentationBlock</code>:</strong>\n<ul class=\"fig-list\"><li>Ausführlicher Dokumentationscontainer.\n</li><li><strong>Stereotyp <code>«atpMixed»</code>:</strong> Definiert gemischten Content (Mischung aus freiem Fließtext, Formatierungsstrukturen und semantischen Metamodell-Inline-Tags).\n</li></ul>\n</li><li><strong><code>SpecElementReference</code> (Abstrakte Spezialisierung):</strong>\n<ul class=\"fig-list\"><li>Generalisiert <code>MultilanguageReferrable</code>.\n</li><li>Attribut:\n<ul class=\"fig-list\"><li><code>alternativeName: String [0..1]</code> – Optionaler Sekundärname bzw. systemspezifischer Alias für das Spezifikationselement.\n</li></ul>\n</li></ul>\n</li><li><strong><code>SpecElementScope</code> (Konkrete Spezialisierung):</strong>\n<ul class=\"fig-list\"><li>Generalisiert <code>SpecElementReference</code>.\n</li><li>Attribut:\n<ul class=\"fig-list\"><li><code>inScope: Boolean [0..1]</code> – Binärer Schalter (<code>true</code> / <code>false</code>) zur expliziten Ein- oder Ausgrenzung des Elements im spezifizierten Kontext.\n</li></ul>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Komposition <code>+desc</code> (<code>0..1</code>):</strong> <code>MultilanguageReferrable</code> aggregiert exklusiv maximal einen <code>MultiLanguageOverviewParagraph</code>.\n</li><li><strong>Komposition <code>+introduction</code> (<code>0..1</code>):</strong> <code>MultilanguageReferrable</code> aggregiert exklusiv maximal einen <code>DocumentationBlock</code>.\n</li><li><strong>Generalisierung:</strong> <code>SpecElementReference</code> erbt von <code>MultilanguageReferrable</code>.\n</li><li><strong>Generalisierung:</strong> <code>SpecElementScope</code> erbt von <code>SpecElementReference</code> (und damit transitiv von <code>Identifiable</code> und <code>Referrable</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Laufzeitverhalten:</strong> Nicht zutreffend (rein deklaratives M2-Strukturmetamodell; keine Ausführung zur Target-Laufzeit auf BSW/RTE-Ebene).\n</li><li><strong>Tooling- &amp; Transformationsablauf (Entwurfszeit):</strong>\n<ol class=\"fig-list\"><li><strong>Deklaration:</strong> Ein Standardization-Profile instanziiert ein <code>SpecElementScope</code> für ein konkretes Spezifikationselement.\n</li><li><strong>Scoping-Prüfung (<code>TPS_STDT_00124</code>):</strong>\n<ul class=\"fig-list\"><li><code>inScope == true</code>: Element ist zwingender/aktiver Bestandteil des definierten Standards/Profils.\n</li><li><code>inScope == false</code>: Element wird explizit als „out of scope“ markiert (wichtig für Profil-Tailoring und Teilspezifikationen).\n</li><li>Fehlt das Attribut (<code>[0..1]</code>), greifen profilweite Default-Semantiken der Standardization-Toolchain.\n</li></ul>\n</li><li><strong>Dokumenten- &amp; Blueprint-Synthese:</strong> Toolchains evaluieren <code>desc</code> und <code>introduction</code> zur automatisierten Dokumenten-Generierung und Blueprint-Validierung.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Target-Auswirkung (Embedded/C++):</strong> Keine direkten Auswirkungen auf MCAL-, BSW- oder SWC-Quellcode. Es existieren keine generierten C-APIs, ISRs oder Mailbox-Strukturen für dieses Metamodell-Element.\n</li><li><strong>Konfigurations- &amp; Modellierungsverträge (ARXML):</strong>\n<ul class=\"fig-list\"><li><code>SpecElementScope</code> wird primär in AUTOSAR Blueprint-Katalogen (<code>AUTOSAR_MOD_StandardizationTemplate.arxml</code>) und Spezifikationsmetadaten verwendet.\n</li><li>Relevanz für Platform-Architekten und Tool-Entwickler: Ermöglicht das präzise Zuschneiden (Tailoring) von Standard-Features für Classic- bzw. Adaptive-Plattformen.\n</li><li>Bei der Definition herstellerspezifischer Derivate verhindert die explizite Kennzeichnung <code>inScope: false</code> Implementierungsambiguitäten bezüglich Konformitätsanforderungen (Compliance Gates / SWS Conformance Testing).\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-5118a7711cf2b8fa", "to": "FIG-9b2d97b54547876a", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
